mapper.select:
SELECT * FROM CARD_TABLE_SCRAP ctj JOIN CARD_TABLE_BENEFIT_SCRAP cbtj ON ctj."id" = cbtj."id" JOIN ( SELECT "id", LISTAGG(benefit_name, ', ') WITHIN GROUP (ORDER BY benefit_name) AS benefits FROM ( SELECT "id", CASE WHEN "fuel" = 1 THEN '주유' END AS benefit_name FROM CARD_TABLE_BENEFIT_SCRAP UNION ALL SELECT "id", CASE WHEN "comm" = 1 THEN '통신' END FROM CARD_TABLE_BENEFIT_SCRAP UNION ALL SELECT "id", CASE WHEN "shop" = 1 THEN '쇼핑' END FROM CARD_TABLE_BENEFIT_SCRAP UNION ALL SELECT "id", CASE WHEN "food" = 1 THEN '푸드' END FROM CARD_TABLE_BENEFIT_SCRAP UNION ALL SELECT "id", CASE WHEN "cafe" = 1 THEN '카페' END FROM CARD_TABLE_BENEFIT_SCRAP ) WHERE benefit_name IS NOT NULL GROUP BY "id" HAVING SUM(CASE WHEN benefit_name IN
#{item}
THEN 1 ELSE 0 END) = #{findBenefitNum} ) sqt ON ctj."id" = sqt."id" WHERE ctj."cate" = #{findCateName} ORDER BY ctj."id" DESC
